$catalog$::jsonb) as r(
  source_id text, source_name text, source_url text, published_at date,
  canonical_name text,
  localized_names jsonb, aliases jsonb, country_code text,
  serving_amount numeric, serving_unit text, calories_kcal numeric,
  protein_g numeric, carbohydrate_g numeric, fat_g numeric, fiber_g numeric,
  sugar_g numeric, sodium_mg numeric, potassium_mg numeric, calcium_mg numeric,
  magnesium_mg numeric, phosphorus_mg numeric, iron_mg numeric,
  vitamin_c_mg numeric, nutrient_evidence_mask integer
))
insert into public.bil_official_food_catalog (
  source_id, source_name, source_url, canonical_name, localized_names, aliases,
  country_code, serving_amount, serving_unit, calories_kcal, protein_g,
  carbohydrate_g, fat_g, fiber_g, sugar_g, sodium_mg, potassium_mg,
  calcium_mg, magnesium_mg, phosphorus_mg, iron_mg, vitamin_c_mg,
  nutrient_evidence_mask, published_at, updated_at
)
select source_id, source_name, source_url, canonical_name, localized_names,
  aliases, country_code, serving_amount, serving_unit, calories_kcal,
  protein_g, carbohydrate_g, fat_g, fiber_g, sugar_g, sodium_mg,
  potassium_mg, calcium_mg, magnesium_mg, phosphorus_mg, iron_mg,
  vitamin_c_mg, nutrient_evidence_mask, published_at, now()
from source_rows
on conflict (source_id) do update set
  source_name = excluded.source_name, source_url = excluded.source_url,
  canonical_name = excluded.canonical_name,
  localized_names = excluded.localized_names, aliases = excluded.aliases,
  country_code = excluded.country_code,
  serving_amount = excluded.serving_amount, serving_unit = excluded.serving_unit,
  calories_kcal = excluded.calories_kcal, protein_g = excluded.protein_g,
  carbohydrate_g = excluded.carbohydrate_g, fat_g = excluded.fat_g,
  fiber_g = excluded.fiber_g, sugar_g = excluded.sugar_g,
  sodium_mg = excluded.sodium_mg, potassium_mg = excluded.potassium_mg,
  calcium_mg = excluded.calcium_mg, magnesium_mg = excluded.magnesium_mg,
  phosphorus_mg = excluded.phosphorus_mg, iron_mg = excluded.iron_mg,
  vitamin_c_mg = excluded.vitamin_c_mg,
  nutrient_evidence_mask = excluded.nutrient_evidence_mask,
  updated_at = now();

